import{_ as o,l as s,o as e,c as i,v as l,p as n,x as t,d,i as p,S as B}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Elo 与 BT 评分","description":"","frontmatter":{"title":"Elo 与 BT 评分","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/elo-bt-rating.md","filePath":"llm/elo-bt-rating.md","lastUpdated":1789023840000}'),E={name:"llm/elo-bt-rating.md"};function _(h,a,m,c,T,A){const r=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=l('<h1 id="elo-与-bt-评分" tabindex="-1">Elo 与 BT 评分 <a class="header-anchor" href="#elo-与-bt-评分" aria-label="Permalink to &quot;Elo 与 BT 评分&quot;">​</a></h1><div class="epigraph"><p>胜负场次是观测，评分是对潜在强度的估计。场次不够时，名次只是噪声的一种排列。</p><footer>—— Bradley-Terry 模型；Elo 作为在线近似；Arena 的用法见 [LMSYS](/llm/lmsys-arena)</footer></div><p><a href="/llm/pairwise-vs-pointwise">上一课</a>把成对选作排名仪器。把许多对战收成一个可排序的标量，常用 Elo 或 Bradley-Terry（BT）。主干 Arena 课已写产品形态；本课补评测进阶里的估计含义。缺口是把「榜上差 20 Elo」当成物理单位。后课风格控制默认：Elo 差可以来自长度，而不是来自强度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BT 假设 \\(P(i\\succ j)=\\sigma(s_i-s_j)\\)，用全体对战的似然估 \\(s\\)。Elo 是对同一差的在线更新，便于实时榜。二者都把传递性写进模型：若循环对战很多（A 胜 B、B 胜 C、C 胜 A），拟合残差会大，单一分数解释力下降。</p><p>场次不平衡：新模型对战少，置信区间宽。只报点估计会制造假名次。对战不是随机设计时（用户自选模型、提示偏代码），\\(s\\) 估计的是<strong>该流量下的强度</strong>，不是无条件能力。</p><p><span class="marginnote">把 Elo 与 MMLU 排进同一张「综合实力」表，是单位错误。一个来自成对口味，一个来自选择题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离线 BT：构造对战表，极大似然或贝叶斯估计 \\(s\\)，用 bootstrap 或 Hessian 报区间。在线 Elo：公布 \\(K\\) 因子与初始分，否则不可复现。过滤：过短对战、明显刷票、同一用户重复，按 Arena 课的纪律。报告应附对战次数矩阵，而不是只附排行。</p>',9)),(e(),n(B,null,{default:t(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%88%90%E5%AF%B9%E8%83%9C%E8%B4%9F%22%5D%20--%3E%20BT%5B%22Bradley-Terry%20%E4%BC%BC%E7%84%B6%22%5D%0A%20%20W%20--%3E%20ELO%5B%22%E5%9C%A8%E7%BA%BF%20Elo%22%5D%0A%20%20BT%20--%3E%20S%5B%22%E5%BC%BA%E5%BA%A6%20s%20%E4%B8%8E%E5%8C%BA%E9%97%B4%22%5D%0A%20%20ELO%20--%3E%20S%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(s_i-s_j\\) 只在 logistic 链接下对应胜率。差 10 与差 100 的胜率含义不同，且依赖是否允许平局、是否有风格协变量。不加协变量时，长度与格式被吸进 \\(s\\)，模型「变强」可能是变长。后课把风格当要控制的变量，而不是当强度。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>BT 不处理多轴偏好（有人要短、有人要长）。混合人群下的单一 \\(s\\) 是投影。下一课风格控制把长度等可观测混淆从 \\(s\\) 里拆出去。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Elo / BT 是成对胜负的强度估计，必须报场次与区间。</li><li>流量偏与非传递性会破坏单一分数。</li><li>未控风格时，\\(s\\) 含长度等混淆。</li><li>出处：Bradley &amp; Terry；Elo；Chatbot Arena 实践。</li></ul>',6))])}const f=o(E,[["render",_]]);export{b as __pageData,f as default};
